<?php $manage = can('printers.manage'); ?>
<div class="top"><div><h2 style="margin:0">Printers</h2><span class="muted"><a href="/staff/queue">Print queue and calendar</a></span></div></div>
<div class="card mb"><div class="tw"><table><tr><th>Name</th><th>Model</th><th>Status</th><th>Next maintenance</th><th class="right">Open jobs</th><th class="right">Printed hours</th><?= $manage ? '<th></th>' : '' ?></tr>
<?php foreach ($rows as $p): $due = $p['next_maintenance'] && $p['next_maintenance'] <= date('Y-m-d', strtotime('+7 days')); ?>
<?php if ($manage): $f = 'pf' . (int) $p['id']; ?><tr><td><input name="name" form="<?= $f ?>" value="<?= e($p['name']) ?>" style="margin:0;min-width:110px"><form id="<?= $f ?>" method="post" action="/staff/printers"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $p['id'] ?>"></form></td>
<td><input name="model" form="<?= $f ?>" value="<?= e((string) $p['model']) ?>" style="margin:0"></td><td><select name="status" form="<?= $f ?>" style="margin:0"><?= options(PRINTER_STATUSES, $p['status']) ?></select></td>
<td><input type="date" name="next_maintenance" form="<?= $f ?>" value="<?= e((string) $p['next_maintenance']) ?>" style="margin:0"></td><td class="right"><?= (int) $p['open_jobs'] ?></td><td class="right"><?= e(number_format((float) $p['hours'], 1)) ?></td>
<td><label style="font-weight:400;white-space:nowrap"><input type="checkbox" name="active" value="1" form="<?= $f ?>" style="width:auto;margin:0 4px 0 0" <?= $p['active'] ? 'checked' : '' ?>>Active</label> <button form="<?= $f ?>" class="btn sm alt">Save</button></td></tr>
<?php else: ?><tr><td><?= e($p['name']) ?></td><td><?= e((string) $p['model']) ?></td><td><?= e(PRINTER_STATUSES[$p['status']]) ?></td><td class="<?= $due ? 'overdue' : '' ?>"><?= e(fmt_date($p['next_maintenance'])) ?></td><td class="right"><?= (int) $p['open_jobs'] ?></td><td class="right"><?= e(number_format((float) $p['hours'], 1)) ?></td></tr><?php endif; ?>
<?php endforeach; if (!$rows): ?><tr><td colspan="7" class="muted">No printers yet.</td></tr><?php endif; ?></table></div></div>
<?php if ($manage): ?><div class="card"><h3>Add a printer</h3><form method="post" action="/staff/printers"><?= csrf_field() ?><div class="row"><div><label>Name</label><input name="name" required maxlength="80" placeholder="e.g. Bambu P1S #1"></div><div><label>Model</label><input name="model" maxlength="120"></div><div><label>Status</label><select name="status"><?= options(PRINTER_STATUSES, 'active') ?></select></div><div><label>Next maintenance</label><input type="date" name="next_maintenance"></div></div><button class="btn">Add printer</button></form></div><?php endif; ?>
